"""wsync 的底层文件系统操作。

所有直接接触磁盘的调用都集中在本模块，这样文件属性、路径形式和共享
冲突的处理就只有一个地方需要关心。
"""

from __future__ import annotations

import os
import shutil
import stat
from typing import Dict, Optional, Tuple

__all__ = [
    "join",
    "path_key",
    "list_entries",
    "stat_signature",
    "is_readonly",
    "remove_file",
    "remove_tree",
    "copy_file",
    "prune_empty_dirs",
]


def join(root: str, relpath: str) -> str:
    """把目标根目录和一个相对路径拼成绝对路径。"""
    return os.path.join(root, relpath)


def path_key(relpath: str) -> str:
    """把相对路径规整成用于比较的键。

    目标平台的文件系统如何认定“两个路径写的是同一个东西”，由本函数
    决定；调用方不应自己再做字符串拼比较。
    """
    return relpath.replace("/", os.sep)


def list_entries(root: str) -> Dict[str, str]:
    """列出目录树中的所有普通文件。

    返回 ``{相对路径: 绝对路径}``；``root`` 不存在时返回空字典。
    """
    entries: Dict[str, str] = {}
    if not os.path.isdir(root):
        return entries
    for dirpath, _dirnames, filenames in os.walk(root):
        for name in filenames:
            full = os.path.join(dirpath, name)
            entries[os.path.relpath(full, root)] = full
    return entries


def stat_signature(path: str) -> Optional[Tuple[int, int]]:
    """返回用于“内容是否变化”判定的签名。

    签名由大小与修改时间共同构成；读取失败时返回 ``None``。
    """
    try:
        info = os.stat(path)
    except OSError:
        return None
    return (info.st_size, info.st_mtime_ns)


def is_readonly(path: str) -> bool:
    """路径是否带有只读属性。"""
    try:
        info = os.stat(path)
    except OSError:
        return False
    return not bool(info.st_mode & stat.S_IWRITE)


def remove_file(path: str) -> None:
    """删除单个文件。"""
    os.remove(path)


def remove_tree(path: str) -> None:
    """递归删除一棵目录树。"""
    shutil.rmtree(path)


def copy_file(source: str, target: str) -> None:
    """把 ``source`` 的内容写到 ``target``，必要时创建父目录。"""
    parent = os.path.dirname(target)
    if parent:
        os.makedirs(parent, exist_ok=True)
    with open(source, "rb") as src_handle, open(target, "wb") as dst_handle:
        shutil.copyfileobj(src_handle, dst_handle, length=1024 * 1024)


def prune_empty_dirs(root: str) -> None:
    """自底向上删除目标树中的空目录（不含 ``root`` 自身）。"""
    root = os.path.abspath(root)
    for dirpath, _dirnames, _filenames in os.walk(root, topdown=False):
        if os.path.abspath(dirpath) == root:
            continue
        try:
            if not os.listdir(dirpath):
                os.rmdir(dirpath)
        except OSError:
            pass

"""执行同步计划。"""

from __future__ import annotations

import os
from dataclasses import dataclass, field
from typing import Dict, List

from . import fsops
from .planner import CREATE, DELETE, KEEP, UPDATE, PlanEntry, build_plan


@dataclass
class SyncResult:
    """一次镜像同步的结果。

    ``created`` / ``updated`` / ``deleted`` / ``kept`` 记录已完成的相对
    路径；``failed`` 记录没有完成的条目，每一项形如::

        {"action": "delete", "relpath": "logs/app.old", "error": "..."}
    """

    created: List[str] = field(default_factory=list)
    updated: List[str] = field(default_factory=list)
    deleted: List[str] = field(default_factory=list)
    kept: List[str] = field(default_factory=list)
    failed: List[Dict[str, str]] = field(default_factory=list)

    @property
    def ok(self) -> bool:
        """没有任何条目失败时为 ``True``。"""
        return not self.failed


def _apply(entry: PlanEntry) -> None:
    if entry.action in (CREATE, UPDATE):
        fsops.copy_file(entry.source, entry.target)
    elif entry.action == DELETE:
        fsops.remove_file(entry.target)


def _record(result: SyncResult, action: str, relpath: str) -> None:
    if action == CREATE:
        result.created.append(relpath)
    elif action == UPDATE:
        result.updated.append(relpath)
    elif action == DELETE:
        result.deleted.append(relpath)


def sync_tree(source_root: str, target_root: str, dry_run: bool = False) -> SyncResult:
    """把 ``source_root`` 镜像同步到 ``target_root``。"""
    source_root = os.path.abspath(source_root)
    target_root = os.path.abspath(target_root)

    if not dry_run:
        os.makedirs(target_root, exist_ok=True)

    plan = build_plan(source_root, target_root)
    result = SyncResult()

    for entry in plan.entries:
        if entry.action == KEEP:
            result.kept.append(entry.relpath)
            continue
        if dry_run:
            _record(result, entry.action, entry.relpath)
            continue
        _apply(entry)
        _record(result, entry.action, entry.relpath)

    if not dry_run:
        fsops.prune_empty_dirs(target_root)

    return result

"""把源树与目标树的差异计算成一份可执行的同步计划。"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import List, Optional

from . import fsops

CREATE = "create"
UPDATE = "update"
DELETE = "delete"
KEEP = "keep"


@dataclass
class PlanEntry:
    """计划中的一条动作。"""

    action: str
    relpath: str
    source: Optional[str] = None
    target: Optional[str] = None


@dataclass
class Plan:
    """一次同步的完整计划。"""

    entries: List[PlanEntry] = field(default_factory=list)

    def actions(self) -> List[str]:
        return [entry.action for entry in self.entries]

    def by_action(self, action: str) -> List[PlanEntry]:
        return [entry for entry in self.entries if entry.action == action]


def needs_update(source_path: str, target_path: str) -> bool:
    """目标文件是否需要被源文件覆盖。"""
    signature = fsops.stat_signature(source_path)
    if signature is None:
        return False
    return signature != fsops.stat_signature(target_path)


def build_plan(source_root: str, target_root: str) -> Plan:
    """计算从 ``source_root`` 到 ``target_root`` 的镜像同步计划。"""
    source_files = fsops.list_entries(source_root)
    target_files = fsops.list_entries(target_root)

    entries: List[PlanEntry] = []

    for relpath in sorted(source_files):
        if relpath not in target_files:
            entries.append(
                PlanEntry(
                    CREATE,
                    relpath,
                    source_files[relpath],
                    fsops.join(target_root, relpath),
                )
            )
        elif needs_update(source_files[relpath], target_files[relpath]):
            entries.append(
                PlanEntry(UPDATE, relpath, source_files[relpath], target_files[relpath])
            )
        else:
            entries.append(
                PlanEntry(KEEP, relpath, source_files[relpath], target_files[relpath])
            )

    for relpath in sorted(target_files):
        if relpath not in source_files:
            entries.append(PlanEntry(DELETE, relpath, None, target_files[relpath]))

    return Plan(entries)

