"""wsync 的底层文件系统操作。

所有直接接触磁盘的调用都集中在本模块，这样文件属性、路径形式和共享
冲突的处理就只有一个地方需要关心。
"""

from __future__ import annotations

import hashlib
import os
import shutil
import stat
from typing import Callable, Dict, Optional, Tuple

__all__ = [
    "join",
    "path_key",
    "list_entries",
    "list_dirs",
    "stat_signature",
    "content_signature",
    "same_content",
    "is_readonly",
    "ensure_writable",
    "remove_file",
    "remove_tree",
    "remove_entry",
    "copy_file",
    "prune_empty_dirs",
]


def join(root: str, relpath: str) -> str:
    """把目标根目录和一个相对路径拼成绝对路径。"""
    return os.path.join(root, relpath)


def path_key(relpath: str) -> str:
    """把相对路径规整成用于比较的键。

    目标平台的文件系统如何认定“两个路径写的是同一个东西”，由本函数
    决定；调用方不应自己再做字符串拼比较。在不区分大小写的文件系统
    （如 Windows 的 NTFS 默认配置）上，仅大小写不同的两个路径会得到
    相同的键。
    """
    return os.path.normcase(os.path.normpath(relpath.replace("/", os.sep)))


def _scan(root: str) -> Tuple[Dict[str, str], Dict[str, str]]:
    """遍历目录树，返回 ``(文件, 目录)`` 两张 ``{相对路径: 绝对路径}`` 表。

    相对路径使用 ``os.sep`` 分隔；``root`` 自身不出现在目录表里。
    """
    files: Dict[str, str] = {}
    dirs: Dict[str, str] = {}
    for dirpath, dirnames, filenames in os.walk(root):
        for name in filenames:
            full = os.path.join(dirpath, name)
            files[os.path.relpath(full, root)] = full
        for name in dirnames:
            full = os.path.join(dirpath, name)
            dirs[os.path.relpath(full, root)] = full
    return files, dirs


def list_entries(root: str) -> Dict[str, str]:
    """列出目录树中的所有普通文件。

    返回 ``{相对路径: 绝对路径}``；``root`` 不存在时返回空字典。
    """
    if not os.path.isdir(root):
        return {}
    files, _dirs = _scan(root)
    return files


def list_dirs(root: str) -> Dict[str, str]:
    """列出目录树中的所有目录（不含 ``root`` 自身）。

    返回 ``{相对路径: 绝对路径}``；``root`` 不存在时返回空字典。
    """
    if not os.path.isdir(root):
        return {}
    _files, dirs = _scan(root)
    return dirs


def stat_signature(path: str) -> Optional[Tuple[int, int]]:
    """返回用于“内容是否变化”快速判定的签名。

    签名由大小与修改时间共同构成；读取失败时返回 ``None``。
    """
    try:
        info = os.stat(path)
    except OSError:
        return None
    return (info.st_size, info.st_mtime_ns)


def content_signature(path: str) -> Optional[Tuple[int, str]]:
    """返回基于文件内容的签名 ``(大小, SHA-256 摘要)``。

    读取失败时返回 ``None``。只读文件同样可以读取。
    """
    try:
        size = os.path.getsize(path)
        digest = hashlib.sha256()
        with open(path, "rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
    except OSError:
        return None
    return (size, digest.hexdigest())


def same_content(source_path: str, target_path: str) -> bool:
    """两个文件的内容是否一致（依据内容本身，而非大小或时间戳）。"""
    source_sig = content_signature(source_path)
    if source_sig is None:
        return False
    return source_sig == content_signature(target_path)


def is_readonly(path: str) -> bool:
    """路径是否带有只读属性。"""
    try:
        info = os.stat(path)
    except OSError:
        return False
    return not bool(info.st_mode & stat.S_IWRITE)


def ensure_writable(path: str) -> None:
    """去掉路径上的只读属性（不存在或本就可写时什么都不做）。"""
    try:
        info = os.stat(path)
    except OSError:
        return
    if not info.st_mode & stat.S_IWRITE:
        os.chmod(path, stat.S_IWRITE)


def _on_rm_error(func: Callable, path: str, _exc_info: object) -> None:
    """``shutil.rmtree`` 的错误回调：去掉只读属性后重试一次。"""
    ensure_writable(path)
    func(path)


def remove_file(path: str) -> None:
    """删除单个文件；只读文件先去掉只读属性再删。"""
    try:
        os.remove(path)
    except PermissionError:
        ensure_writable(path)
        os.remove(path)


def remove_tree(path: str) -> None:
    """递归删除一棵目录树，途中遇到的只读条目自动去掉只读属性。"""
    ensure_writable(path)
    shutil.rmtree(path, onerror=_on_rm_error)


def remove_entry(path: str) -> None:
    """删除一条路径：是目录则递归删除整棵子树，否则删除文件。"""
    if os.path.isdir(path):
        remove_tree(path)
    else:
        remove_file(path)


def copy_file(source: str, target: str) -> None:
    """把 ``source`` 的内容写到 ``target``，必要时创建父目录。

    目标已存在且只读时先去掉只读属性再覆盖；写完后把源的修改时间
    同步到目标上，使后续同步可以依据时间戳快速判定“没有变化”。
    """
    parent = os.path.dirname(target)
    if parent:
        os.makedirs(parent, exist_ok=True)
    if os.path.exists(target):
        ensure_writable(target)
    with open(source, "rb") as src_handle, open(target, "wb") as dst_handle:
        shutil.copyfileobj(src_handle, dst_handle, length=1024 * 1024)
    shutil.copystat(source, target)


def prune_empty_dirs(root: str) -> None:
    """自底向上删除目标树中的空目录（不含 ``root`` 自身）。

    只读的空目录先去掉只读属性再删除；仍然删不掉的（例如被其它进程
    占用）跳过，由调用方决定是否记入失败清单。
    """
    root = os.path.abspath(root)
    for dirpath, _dirnames, _filenames in os.walk(root, topdown=False):
        if os.path.abspath(dirpath) == root:
            continue
        try:
            if not os.listdir(dirpath):
                try:
                    os.rmdir(dirpath)
                except PermissionError:
                    ensure_writable(dirpath)
                    os.rmdir(dirpath)
        except OSError:
            pass

"""把源树与目标树的差异计算成一份可执行的同步计划。"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Dict, List, Optional, Tuple

from . import fsops

CREATE = "create"
UPDATE = "update"
DELETE = "delete"
KEEP = "keep"


@dataclass
class PlanEntry:
    """计划中的一条动作。"""

    action: str
    relpath: str
    source: Optional[str] = None
    target: Optional[str] = None


@dataclass
class Plan:
    """一次同步的完整计划。"""

    entries: List[PlanEntry] = field(default_factory=list)

    def actions(self) -> List[str]:
        return [entry.action for entry in self.entries]

    def by_action(self, action: str) -> List[PlanEntry]:
        return [entry for entry in self.entries if entry.action == action]


def _index_by_key(relpaths) -> Dict[str, str]:
    """把相对路径列表按 :func:`fsops.path_key` 归一键索引。

    归一键冲突（同一目录下出现仅大小写不同的两个名字）时保留排序后
    的第一个，保证结果是确定性的。
    """
    indexed: Dict[str, str] = {}
    for relpath in sorted(relpaths):
        indexed.setdefault(fsops.path_key(relpath), relpath)
    return indexed


def needs_update(source_path: str, target_path: str) -> bool:
    """目标文件是否需要被源文件覆盖。

    判定依据内容本身：大小或修改时间不同可以直接认定需要更新；两者
    都相同（上游工具可能就地改写并保留时间戳）时再比较内容。
    """
    signature = fsops.stat_signature(source_path)
    if signature is None:
        return False
    if signature != fsops.stat_signature(target_path):
        return True
    return not fsops.same_content(source_path, target_path)


def _parent_keys(relpath: str) -> List[str]:
    """返回 ``relpath`` 全部上级分量的归一键（由浅到深）。"""
    parts = relpath.replace("/", fsops.os.sep).split(fsops.os.sep)
    keys = []
    for i in range(1, len(parts)):
        keys.append(fsops.path_key(fsops.os.sep.join(parts[:i])))
    return keys


def _resolve_conflicts(
    source_files: Dict[str, str],
    source_dirs: Dict[str, str],
    target_files: Dict[str, str],
    target_dirs: Dict[str, str],
) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str], Dict[str, str]]:
    """消解源与目标在同一路径上的类型冲突。

    返回过滤后的四张表。凡是被认定构成冲突的目标条目，都从常规差异
    计算中剔除——它们会由执行阶段在落地源条目之前单独清理，清理只
    影响构成冲突的那条路径本身。
    """
    source_file_keys = _index_by_key(source_files)
    source_dir_keys = _index_by_key(source_dirs)
    target_file_keys = _index_by_key(target_files)
    target_dir_keys = _index_by_key(target_dirs)

    # 目标侧构成冲突的条目（归一键集合）：
    #  - 目标文件占住了源中某个目录的位置（含源文件的上级分量）；
    #  - 目标目录占住了源中某个文件的位置（含源目录的上级分量）。
    conflict_target_files = set()
    conflict_target_dirs = set()

    for key in target_file_keys:
        if key in source_dir_keys:
            conflict_target_files.add(key)

    for key in target_dir_keys:
        if key in source_file_keys:
            conflict_target_dirs.add(key)

    # 上级分量冲突：源里 ``a/b/c.txt`` 而目标里 ``a/b`` 是文件等。
    for relpath in source_files:
        for key in _parent_keys(relpath):
            if key in target_file_keys:
                conflict_target_files.add(key)
            if key in target_dir_keys:
                conflict_target_dirs.add(key)
    for relpath in source_dirs:
        for key in _parent_keys(relpath):
            if key in target_file_keys:
                conflict_target_files.add(key)
            if key in target_dir_keys:
                conflict_target_dirs.add(key)

    def _drop(table: Dict[str, str], doomed: set) -> Dict[str, str]:
        return {
            relpath: full
            for relpath, full in table.items()
            if fsops.path_key(relpath) not in doomed
        }

    # 冲突的目标目录整棵剔除：它会被整体清理，里面的文件不再单独
    # 生成删除动作，避免重复清理误伤清理后新落地的内容。
    doomed_dir_keys = conflict_target_dirs

    def _under_doomed_dir(relpath: str) -> bool:
        return any(key in doomed_dir_keys for key in _parent_keys(relpath))

    new_target_files = {
        relpath: full
        for relpath, full in _drop(target_files, conflict_target_files).items()
        if not _under_doomed_dir(relpath)
    }
    new_target_dirs = {
        relpath: full
        for relpath, full in _drop(target_dirs, conflict_target_dirs).items()
        if not _under_doomed_dir(relpath)
    }

    # 冲突的目标文件被清理后，源中对应位置的目录必须能落地：源目录
    # 之下、以该冲突文件为“父目录”的源文件在目标侧必然缺失，按新建
    # 处理即可，不需要额外过滤源表。
    return source_files, source_dirs, new_target_files, new_target_dirs


def build_plan(source_root: str, target_root: str) -> Plan:
    """计算从 ``source_root`` 到 ``target_root`` 的镜像同步计划。"""
    source_files = fsops.list_entries(source_root)
    source_dirs = fsops.list_dirs(source_root)
    target_files = fsops.list_entries(target_root)
    target_dirs = fsops.list_dirs(target_root)

    source_files, source_dirs, target_files, target_dirs = _resolve_conflicts(
        source_files, source_dirs, target_files, target_dirs
    )

    # 以平台归一键匹配源与目标：不区分大小写的文件系统上，仅大小写
    # 不同的两个路径被认定为同一个文件。
    target_file_keys = _index_by_key(target_files)
    source_file_keys = _index_by_key(source_files)

    entries: List[PlanEntry] = []

    for relpath in sorted(source_files):
        key = fsops.path_key(relpath)
        target_relpath = target_file_keys.get(key)
        if target_relpath is None:
            entries.append(
                PlanEntry(
                    CREATE,
                    relpath,
                    source_files[relpath],
                    fsops.join(target_root, relpath),
                )
            )
        elif needs_update(source_files[relpath], target_files[target_relpath]):
            entries.append(
                PlanEntry(
                    UPDATE,
                    relpath,
                    source_files[relpath],
                    target_files[target_relpath],
                )
            )
        else:
            entries.append(
                PlanEntry(
                    KEEP,
                    relpath,
                    source_files[relpath],
                    target_files[target_relpath],
                )
            )

    for relpath in sorted(target_files):
        if fsops.path_key(relpath) not in source_file_keys:
            entries.append(PlanEntry(DELETE, relpath, None, target_files[relpath]))

    return Plan(entries)

"""把源树与目标树的差异计算成一份可执行的同步计划。"""

from __future__ import annotations

import os
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Set, Tuple

from . import fsops

CREATE = "create"
UPDATE = "update"
