    relpath: str
    source: Optional[str] = None
    target: Optional[str] = None


@dataclass
class Plan:
    """一次同步的完整计划。"""

    entries: List[PlanEntry] = field(default_factory=list)

    def actions(self) -> List[str]:
        return [entry.action for entry in self.entries]

    def by_action(self, action: str) -> List[PlanEntry]:
        return [entry for entry in self.entries if entry.action == action]


def _index_by_key(relpaths) -> Dict[str, str]:
    """把相对路径列表按 :func:`fsops.path_key` 归一键索引。

    归一键冲突（同一目录下出现仅大小写不同的两个名字）时保留排序后
    的第一个，保证结果是确定性的。
    """
    indexed: Dict[str, str] = {}
    for relpath in sorted(relpaths):
        indexed.setdefault(fsops.path_key(relpath), relpath)
    return indexed


def needs_update(source_path: str, target_path: str) -> bool:
    """目标文件是否需要被源文件覆盖。

    判定依据内容本身：大小或修改时间不同可以直接认定需要更新；两者
    都相同（上游工具可能就地改写并保留时间戳）时再比较内容。
    """
    signature = fsops.stat_signature(source_path)
    if signature is None:
        return False
    if signature != fsops.stat_signature(target_path):
        return True
    return not fsops.same_content(source_path, target_path)


def _parent_keys(relpath: str) -> List[str]:
    """返回 ``relpath`` 全部上级分量的归一键（由浅到深）。"""
    parts = relpath.replace("/", os.sep).split(os.sep)
    keys = []
    for i in range(1, len(parts)):
        keys.append(fsops.path_key(os.sep.join(parts[:i])))
    return keys


def _resolve_conflicts(
    source_files: Dict[str, str],
    source_dirs: Dict[str, str],
    target_files: Dict[str, str],
    target_dirs: Dict[str, str],
) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str], Dict[str, str]]:
    """消解源与目标在同一路径上的类型冲突。

    返回过滤后的四张表。凡是被认定构成冲突的目标条目，都从常规差异
    计算中剔除——它们会由执行阶段在落地源条目之前单独清理，清理只
    影响构成冲突的那条路径本身。
    """
    source_file_keys = _index_by_key(source_files)
    source_dir_keys = _index_by_key(source_dirs)
    target_file_keys = _index_by_key(target_files)
    target_dir_keys = _index_by_key(target_dirs)

    # 目标侧构成冲突的条目（归一键集合）：
    #  - 目标文件占住了源中某个目录的位置（含源条目的上级分量）；
    #  - 目标目录占住了源中某个文件的位置（含源条目的上级分量）。
    conflict_target_files: Set[str] = set()
    conflict_target_dirs: Set[str] = set()

    for key in target_file_keys:
        if key in source_dir_keys:
            conflict_target_files.add(key)

    for key in target_dir_keys:
        if key in source_file_keys:
            conflict_target_dirs.add(key)

    # 上级分量冲突：源里 ``a/b/c.txt`` 而目标里 ``a/b`` 是文件等。
    for relpath in source_files:
        for key in _parent_keys(relpath):
            if key in target_file_keys:
                conflict_target_files.add(key)
            if key in target_dir_keys:
                conflict_target_dirs.add(key)
    for relpath in source_dirs:
        for key in _parent_keys(relpath):
            if key in target_file_keys:
                conflict_target_files.add(key)
            if key in target_dir_keys:
                conflict_target_dirs.add(key)

    def _drop(table: Dict[str, str], doomed: Set[str]) -> Dict[str, str]:
        return {
            relpath: full
            for relpath, full in table.items()
            if fsops.path_key(relpath) not in doomed
        }

    # 冲突的目标目录会被整体清理，它里面的文件与子目录不再单独生成
    # 删除动作，避免重复清理误伤清理后新落地的内容。
    doomed_dir_keys = conflict_target_dirs

    def _under_doomed_dir(relpath: str) -> bool:
        return any(key in doomed_dir_keys for key in _parent_keys(relpath))

    new_target_files = {
        relpath: full
        for relpath, full in _drop(target_files, conflict_target_files).items()
        if not _under_doomed_dir(relpath)
    }
    new_target_dirs = {
        relpath: full
        for relpath, full in _drop(target_dirs, conflict_target_dirs).items()
        if not _under_doomed_dir(relpath)
    }

    return source_files, source_dirs, new_target_files, new_target_dirs


def build_plan(source_root: str, target_root: str) -> Plan:
    """计算从 ``source_root`` 到 ``target_root`` 的镜像同步计划。"""
    source_files = fsops.list_entries(source_root)
    source_dirs = fsops.list_dirs(source_root)
    target_files = fsops.list_entries(target_root)
    target_dirs = fsops.list_dirs(target_root)

    source_files, source_dirs, target_files, target_dirs = _resolve_conflicts(
        source_files, source_dirs, target_files, target_dirs
    )

    # 以平台归一键匹配源与目标：不区分大小写的文件系统上，仅大小写
    # 不同的两个路径被认定为同一个文件。
    target_file_keys = _index_by_key(target_files)
    source_file_keys = _index_by_key(source_files)

    entries: List[PlanEntry] = []

    for relpath in sorted(source_files):
        key = fsops.path_key(relpath)
        target_relpath = target_file_keys.get(key)
        if target_relpath is None:
            entries.append(
                PlanEntry(
                    CREATE,
                    relpath,
                    source_files[relpath],
                    fsops.join(target_root, relpath),
                )
            )
        elif needs_update(source_files[relpath], target_files[target_relpath]):
            entries.append(
                PlanEntry(
                    UPDATE,
                    relpath,
                    source_files[relpath],
                    target_files[target_relpath],
                )
            )
        else:
            entries.append(
                PlanEntry(
                    KEEP,
                    relpath,
                    source_files[relpath],
                    target_files[target_relpath],
                )
            )

    for relpath in sorted(target_files):
        if fsops.path_key(relpath) not in source_file_keys:
            entries.append(PlanEntry(DELETE, relpath, None, target_files[relpath]))

    return Plan(entries)

"""执行同步计划。"""

