import os
from dataclasses import dataclass, field
from typing import Dict, List

from . import fsops
from .planner import CREATE, DELETE, KEEP, UPDATE, PlanEntry, build_plan


@dataclass
class SyncResult:
    """一次镜像同步的结果。

    ``created`` / ``updated`` / ``deleted`` / ``kept`` 记录已完成的相对
    路径；``failed`` 记录没有完成的条目，每一项形如::

        {"action": "delete", "relpath": "logs/app.old", "error": "..."}
    """

    created: List[str] = field(default_factory=list)
    updated: List[str] = field(default_factory=list)
    deleted: List[str] = field(default_factory=list)
    kept: List[str] = field(default_factory=list)
    failed: List[Dict[str, str]] = field(default_factory=list)

    @property
    def ok(self) -> bool:
        """没有任何条目失败时为 ``True``。"""
        return not self.failed


def _clear_conflicting_target(target: str) -> None:
    """清掉占住 ``target`` 及其上级分量的异类型条目。

    只在目标路径当前无法按预期类型使用时才动手：要落地文件的位置被
    一棵目录占住，或者它的某个上级分量被一个文件占住。清理只影响
    构成冲突的那条路径本身，不波及其它条目。
    """
    # 上级分量被同名文件占住（例如要落地 ``a/b/c.txt`` 而 ``a/b`` 是文件）。
    parent = os.path.dirname(target)
    if parent and not os.path.isdir(parent):
        blockers = []
        cursor = parent
        while cursor and not os.path.isdir(cursor):
            blockers.append(cursor)
            next_cursor = os.path.dirname(cursor)
            if next_cursor == cursor:
                break
            cursor = next_cursor
        for blocker in reversed(blockers):
            if os.path.isdir(blocker):
                continue  # 竞态下已被其它步骤建好
            fsops.remove_entry(blocker)

    # 目标位置本身被一棵目录占住（源里是文件）。
    if os.path.isdir(target):
        fsops.remove_tree(target)


def _apply(entry: PlanEntry) -> None:
    if entry.action in (CREATE, UPDATE):
        _clear_conflicting_target(entry.target)
        fsops.copy_file(entry.source, entry.target)
    elif entry.action == DELETE:
        fsops.remove_entry(entry.target)


def _record(result: SyncResult, action: str, relpath: str) -> None:
    if action == CREATE:
        result.created.append(relpath)
    elif action == UPDATE:
        result.updated.append(relpath)
    elif action == DELETE:
        result.deleted.append(relpath)


def _prune_empty_dirs(target_root: str, result: SyncResult) -> None:
    """自底向上删除目标树中的空目录（不含 ``target_root`` 自身）。

    只读的空目录先去掉只读属性再删；仍然删不掉的记入失败清单，
    不影响本次同步的其余部分。
    """
    root = os.path.abspath(target_root)
    for dirpath, _dirnames, _filenames in os.walk(root, topdown=False):
        if os.path.abspath(dirpath) == root:
            continue
        relpath = os.path.relpath(dirpath, root)
        try:
            if os.listdir(dirpath):
                continue
        except OSError:
            continue
        try:
            try:
                os.rmdir(dirpath)
            except PermissionError:
                fsops.ensure_writable(dirpath)
                os.rmdir(dirpath)
        except OSError as exc:
            result.failed.append(
                {"action": DELETE, "relpath": relpath, "error": str(exc)}
            )


def sync_tree(source_root: str, target_root: str, dry_run: bool = False) -> SyncResult:
    """把 ``source_root`` 镜像同步到 ``target_root``。

    单个条目处理失败（例如被其它进程占用）不会中断整次同步：该条目
    记入返回结果的 ``failed``，其余条目继续完成。只读条目会先自动
    去掉只读属性再处理，属于可以自动修复的情况，不会记成失败。
    """
    source_root = os.path.abspath(source_root)
    target_root = os.path.abspath(target_root)

    if not dry_run:
        os.makedirs(target_root, exist_ok=True)

    plan = build_plan(source_root, target_root)
    result = SyncResult()

    for entry in plan.entries:
        if entry.action == KEEP:
            result.kept.append(entry.relpath)
            continue
        if dry_run:
            _record(result, entry.action, entry.relpath)
            continue
        try:
            _apply(entry)
        except OSError as exc:
            result.failed.append(
                {"action": entry.action, "relpath": entry.relpath, "error": str(exc)}
            )
            continue
        _record(result, entry.action, entry.relpath)

    if not dry_run:
        _prune_empty_dirs(target_root, result)

    return result

