            )
        else:
            entries.append(
                PlanEntry(
                    KEEP,
                    relpath,
                    source_files[relpath],
                    target_files[target_relpath],
                )
            )

    for relpath in sorted(target_files):
        if fsops.path_key(relpath) not in source_file_keys:
            entries.append(PlanEntry(DELETE, relpath, None, target_files[relpath]))

    return Plan(entries)
